    unsigned int v1 = in[1];
    unsigned int sum = 0;
    for (int i = 0; i < 32; ++i) {
        v0 += (((v1 >> 5) ^ (v1 << 4)) + v1) ^ (sum + key[sum & 3]);
        sum += 0x9E3779B9u;
        v1 += (((v0 >> 5) ^ (v0 << 4)) + v0) ^ (sum + key[(sum >> 11) & 3]);
    }
    out[0] = v0;
    out[1] = v1;
}

